		}
		input = eventtest.ChildForProducerWithRoutingSource(uuid.NewString(), publication, eventtest.Producer(events.EventProducerPlatform, "workflow"), "", payload, 1, lineage, events.EnvelopeForFlowInstance(events.EnvelopeForEntityID(events.EventEnvelope{}, child.EntityID), child.InstancePath), routingSource, at.Add(time.Second))
		input, err = eventtest.AdmitPayload(input, child.TemplateID, "work.ready")
		if err != nil {
			t.Fatal(err)
		}
		eventID = input.ID()
	}
	materialized, err := manager.ConstructedFlowMaterialization(loaded.Source, runID, child)
	if err != nil || len(materialized.Agents) != 1 {
		t.Fatalf("exact constructed child declaration: plan=%#v err=%v", materialized, err)
	}
