	for table, rows := range before {
		if table == "runs" {
			continue
		}
		for _, row := range rows {
			if strings.Contains(row, runID) && !slices.Contains(after[table], row) {
				t.Fatalf("fork changed source evidence in %s: %s", table, row)
			}
		}
	}
}

