				if err != nil {
					t.Fatalf("construct runtime context %s: %v", fact.BundleHash(), err)
				}
				runtimes = append(runtimes, rt)
			}
			capability, err := selected.StartupOwnership().AcquireProcessCapability(context.Background(), runtimestartupownership.AcquireRequest{OwnerID: "dynamic-topology-preflight-test", BootID: uuid.NewString(), RuntimeInstanceID: runtimeInstanceID})
			if err != nil {
				t.Fatal(err)
			}
